const fs=require('fs');
const N3=require('n3');
const {Parser}=N3;
const ttl=fs.readFileSync('/app/university_graph.ttl','utf8');
const parser=new Parser();
const quads=parser.parse(ttl);
console.log('quads',quads.length);
const NS='http://university.org/ontology/';
const g=(s,p,o)=>quads.filter(q=> (!s||q.subject.value===s)&&(!p||q.predicate.value===p)&&(!o||q.object.value===o));
// list persons with roles
const hasName=g(null,NS+'hasName',null);
for(const q of quads.filter(q=>q.predicate.value===NS+'role')){
  console.log(q.subject.value, '|', q.object.value);
}
console.log('---worksIn---');
for(const q of quads.filter(q=>q.predicate.value===NS+'worksIn')){
  console.log(q.subject.value, 'worksIn', q.object.value);
}
console.log('---dept->univ->country---');
for(const q of quads.filter(q=>q.predicate.value===NS+'belongsTo')){
  const dept=q.subject.value; const univ=q.object.value;
  const c=quads.find(x=>x.subject.value===univ && x.predicate.value===NS+'locatedInCountry');
  console.log(dept,'->',univ, c?c.object.value:'?');
}
console.log('---course->dept---');
for(const q of quads.filter(q=>q.predicate.value===NS+'isTaughtIn')){
  console.log(q.subject.value,'taughtIn',q.object.value);
}
// enrollment analysis with ref date 2025-08-16
const ref='2025-08-16';
function isCurrent(enroll, grad){
  if(enroll>ref) return false;
  if(!grad) return true;
  return grad>ref;
}
// map student -> enroll, grad, courses
const students={};
for(const q of quads.filter(q=>q.predicate.value===NS+'isEnrolledIn')){
  const s=q.subject.value; const c=q.object.value;
  if(!students[s]) students[s]={courses:[],enroll:null,grad:null};
  students[s].courses.push(c);
}
for(const q of quads.filter(q=>q.predicate.value===NS+'hasEnrollmentDate')){
  const s=q.subject.value; if(!students[s]) students[s]={courses:[],enroll:null,grad:null};
  students[s].enroll=q.object.value;
}
for(const q of quads.filter(q=>q.predicate.value===NS+'hasGraduationDate')){
  const s=q.subject.value; if(!students[s]) students[s]={courses:[],enroll:null,grad:null};
  students[s].grad=q.object.value;
}
for(const [s,v] of Object.entries(students)){
  console.log(s, JSON.stringify(v), 'current='+isCurrent(v.enroll,v.grad));
}
// per dept distinct current students
const courseToDept={};
for(const q of quads.filter(q=>q.predicate.value===NS+'isTaughtIn')) courseToDept[q.subject.value]=q.object.value;
const deptStudents={};
for(const [s,v] of Object.entries(students)){
  if(!isCurrent(v.enroll,v.grad)) continue;
  for(const c of v.courses){
    const d=courseToDept[c];
    if(!d){ console.log('WARN course without dept',c,'for',s); continue; }
    if(!deptStudents[d]) deptStudents[d]=new Set();
    deptStudents[d].add(s);
  }
}
console.log('---dept current counts---');
for(const [d,set] of Object.entries(deptStudents)) console.log(d, set.size, [...set].join(','));
// also check all depts with zero
const allDepts=[...new Set(quads.filter(q=>q.predicate.value===NS+'belongsTo').map(q=>q.subject.value))];
for(const d of allDepts) if(!deptStudents[d]) console.log(d, 0);
